1→function me = loadMotionEnergy(obj,meta,params,datapth,varargin)
     2→
     3→if nargin > 4
     4→    returnAfterLoad = varargin{1};
     5→else
     6→    returnAfterLoad = 0;
     7→end
     8→
     9→% %------------------------------------------------------------
    10→% % --first check to see if obj has an 'me' and has thresh--
    11→% % -----------------------------------------------------------
    12→% if isfield(obj,'me')
    13→%     if isstruct(obj.me) && ~iscell(obj.me.data)
    14→%         obj.me.move = obj.me.data > (obj.me.moveThresh);
    15→%         me = obj.me;
    16→%         return
    17→%     end
    18→% else
    19→% -----------------------------------------------------------
    20→% -- if not, loadMotionEnergy, and save it it to obj.me--
    21→% -----------------------------------------------------------
    22→
    23→% find and load motion energy .mat file
    24→mepth = fullfile(datapth,'DataObjects',meta.anm);
    25→contents = dir(mepth);
    26→contents = contents(~[contents.isdir]);
    27→
    28→fns = {contents.name}';
    29→
    30→fn = patternMatchCellArray({contents.name}',{'motionEnergy',meta.date},'all');
    31→
    32→if numel(fn) == 1
    33→    fn = fn{1};
    34→elseif numel(fn) == 2
    35→    ix = ~contains(fn,'._'); % on windows, sometimes a file that starts with '._motionEnergy*' is found
    36→    fn = fn{ix};
    37→else
    38→    disp('UNABLE TO LOCATE A MOTION ENERGY FILE IN: ')
    39→    disp(mepth)
    40→    disp('      Continuing without motion energy as a feature')
    41→    me.use = 0;
    42→    me.data = nan;
    43→    me.moveThresh = nan;
    44→    return
    45→end
    46→
    47→temp = load(fullfile(mepth,fn));
    48→me = temp.me;
    49→
    50→if isstruct(me.data)
    51→    me.data = me.data.data;
    52→end
    53→
    54→if returnAfterLoad
    55→    return
    56→end
    57→
    58→vidshift = findVideoOffset(obj);
    59→% vidshift = 1;
    60→
    61→% -----------------------------------------------------------
    62→% trim trial length (me.data contains motion energy for each time point in
    63→% trial at 400 Hz). Want to align to params.alignEvent and want to put it
    64→% in same dt as neural data
    65→% -----------------------------------------------------------
    66→taxis = obj.time + params.advance_movement;
    67→alignTimes = obj.bp.ev.(params.alignEvent);
    68→me.newdata = zeros(numel(obj.time),numel(me.data));
    69→for trix = 1:numel(me.data)
